<section class="mt-7 flex flex-wrap items-end justify-between gap-4"><div><h2 class="text-xl font-extrabold">Users & companies</h2><p class="text-sm text-[#78908c]">Manage the accounts below your level without separate login tables.</p></div><button onclick="document.getElementById('newAccount').showModal()" class="btn btn-primary"><i data-lucide="user-plus" class="h-4"></i>Create account</button></section><section class="card mt-6 overflow-x-auto p-5"><table class="w-full min-w-[760px] text-left text-sm"><thead class="text-[10px] uppercase text-[#879e9a]"><tr><th class="pb-3">Name</th><th>Email</th><th>Level</th><th>Company</th><th>Status</th><th></th></tr></thead><tbody class="divide-y divide-[#dbeae7]"><?php foreach($accounts as $a): ?><tr><td class="py-4 font-bold"><?= esc(trim($a['first_name'].' '.$a['last_name'])) ?></td><td><?= esc($a['email']??'—') ?></td><td><span class="rounded-full bg-[#dff4e9] px-2 py-1 text-xs font-bold text-[#25775f]"><?= esc(ucwords(str_replace('_',' ',$a['account_type']))) ?></span></td><td><?= esc($a['company_name']??'—') ?></td><td><?= esc(ucfirst($a['status'])) ?></td><td><a class="btn shadow-soft" href="<?= portal_url('accounts/'.$a['uuid'].'/permissions') ?>">Permissions</a></td></tr><?php endforeach ?></tbody></table></section>
<dialog id="newAccount" class="w-full max-w-lg rounded-3xl bg-mist p-6 shadow-2xl backdrop:bg-[#153b39]/30"><div class="flex justify-between"><h3 class="text-xl font-extrabold">Create account</h3><button onclick="this.closest('dialog').close()"><i data-lucide="x"></i></button></div><form action="<?= portal_url('accounts') ?>" method="post" class="mt-5 space-y-3"><?= csrf_field() ?><div class="grid grid-cols-2 gap-3"><input name="first_name" required class="field" placeholder="First name"><input name="last_name" class="field" placeholder="Last name"></div><input name="company_name" class="field" placeholder="Company"><input name="email" type="email" required class="field" placeholder="Email"><input name="password" type="password" minlength="10" required class="field" placeholder="Temporary password"><select name="account_type" required class="field"><?php foreach($allowedTypes as $type): ?><option value="<?= esc($type) ?>"><?= esc(ucwords(str_replace('_',' ',$type))) ?></option><?php endforeach ?></select><button class="btn btn-primary w-full justify-center">Create and activate</button></form></dialog>
